// Package domain holds Hanko's entities, value types and rules.
// It imports no infrastructure. Vocabulary follows docs/GLOSSARIO.md (ADR-0016).
package domain

import (
	"encoding/json"
	"strings"
	"time"

	"github.com/google/uuid"
)

// ID is a UUIDv7 identifier generated by the application.
type ID = uuid.UUID

// NewID returns a new time-ordered UUIDv7.
func NewID() ID { return uuid.Must(uuid.NewV7()) }

// ActorType identifies who caused a fact.
type ActorType string

const (
	ActorHuman   ActorType = "human"
	ActorPersona ActorType = "persona"
	ActorSystem  ActorType = "system"
)

func (a ActorType) Valid() bool { return a == ActorHuman || a == ActorPersona || a == ActorSystem }

// Actor is the author of a write. ID is nil for system and for the trusted local human.
type Actor struct {
	Type ActorType `json:"type"`
	ID   *ID       `json:"id,omitempty"`
}

var (
	SystemActor = Actor{Type: ActorSystem}
	HumanActor  = Actor{Type: ActorHuman}
)

func PersonaActor(id ID) Actor { return Actor{Type: ActorPersona, ID: &id} }

// Company is the unit of multi-org isolation.
type Company struct {
	ID         ID     `json:"id"`
	Slug       string `json:"slug"`
	Name       string `json:"name"`
	TaskPrefix string `json:"task_prefix"` // e.g. "HNK" → task keys HNK-12
	Timezone   string `json:"timezone"`
	// BudgetMonthlyCents is the monthly spend ceiling in USD cents; nil = no ceiling.
	BudgetMonthlyCents *int64    `json:"budget_monthly_cents,omitempty"`
	CreatedAt          time.Time `json:"created_at"`
	UpdatedAt          time.Time `json:"updated_at"`
}

// Workspace is a directory/repository where personas work; it scopes memory.
type Workspace struct {
	ID        ID     `json:"id"`
	CompanyID ID     `json:"company_id"`
	Slug      string `json:"slug"`
	Name      string `json:"name"`
	Path      string `json:"path"`
	RepoURL   string `json:"repo_url,omitempty"`
	// DefaultBranch is the branch the team works on; metadata only (Hanko never clones or switches branches).
	DefaultBranch string    `json:"default_branch,omitempty"`
	CreatedAt     time.Time `json:"created_at"`
	UpdatedAt     time.Time `json:"updated_at"`
}

// ProjectStatus is the lifecycle of a project: an archived one takes no new tasks.
type ProjectStatus string

const (
	ProjectActive   ProjectStatus = "active"
	ProjectArchived ProjectStatus = "archived"
)

// Valid reports whether s is a known project status.
func (s ProjectStatus) Valid() bool { return s == ProjectActive || s == ProjectArchived }

// Project groups tasks. It may own a workspace (the working directory of its tasks' runs) and a monthly
// budget of its own.
type Project struct {
	ID          ID            `json:"id"`
	CompanyID   ID            `json:"company_id"`
	Slug        string        `json:"slug"`
	Name        string        `json:"name"`
	Description string        `json:"description,omitempty"`
	WorkspaceID *ID           `json:"workspace_id,omitempty"`
	Status      ProjectStatus `json:"status"`
	// BudgetMonthlyCents is the project's monthly ceiling in USD cents; nil = no ceiling.
	BudgetMonthlyCents *int64    `json:"budget_monthly_cents,omitempty"`
	CreatedAt          time.Time `json:"created_at"`
	UpdatedAt          time.Time `json:"updated_at"`
}

// WorkspaceSource tells where the working directory of a run came from. Precedence: the workspace chosen on the
// task > the project's > the persona's > none (a per-run temporary directory).
type WorkspaceSource string

const (
	WorkspaceFromTask    WorkspaceSource = "task"
	WorkspaceFromProject WorkspaceSource = "project"
	WorkspaceFromPersona WorkspaceSource = "persona"
	WorkspaceNone        WorkspaceSource = "none"
)

// PersonaStatus is the lifecycle state of a persona.
type PersonaStatus string

const (
	PersonaActive       PersonaStatus = "active"
	PersonaIdle         PersonaStatus = "idle"
	PersonaRunning      PersonaStatus = "running"
	PersonaPaused       PersonaStatus = "paused"
	PersonaError        PersonaStatus = "error"
	PersonaAwaitingGate PersonaStatus = "awaiting_gate"
	PersonaOff          PersonaStatus = "off"
)

func (s PersonaStatus) Valid() bool {
	switch s {
	case PersonaActive, PersonaIdle, PersonaRunning, PersonaPaused, PersonaError, PersonaAwaitingGate, PersonaOff:
		return true
	}
	return false
}

// CanWork reports whether the heartbeat may start runs for the persona.
func (s PersonaStatus) CanWork() bool {
	return s == PersonaActive || s == PersonaIdle || s == PersonaRunning
}

// Persona is a role hired by a company (CTO, engineer, reviewer).
// Agent is the harness that executes it (claude, codex, acp, fake).
type Persona struct {
	ID        ID     `json:"id"`
	CompanyID ID     `json:"company_id"`
	Slug      string `json:"slug"`
	Name      string `json:"name"`
	Title     string `json:"title"`
	// Icon é o glifo de linha da persona (um de PersonaIcons; padrão "bot").
	Icon                 string          `json:"icon"`
	Instructions         string          `json:"instructions"`
	Agent                string          `json:"agent"`
	Model                string          `json:"model,omitempty"`
	AdapterConfig        json.RawMessage `json:"adapter_config,omitempty"`
	Status               PersonaStatus   `json:"status"`
	ReportsTo            *ID             `json:"reports_to,omitempty"`
	WorkspaceID          *ID             `json:"workspace_id,omitempty"`
	HeartbeatIntervalSec int             `json:"heartbeat_interval_sec"`
	BudgetMonthlyCents   *int64          `json:"budget_monthly_cents,omitempty"`
	// SubscriptionID is the optional plan (assinatura) that covers this persona's runs.
	SubscriptionID *ID `json:"subscription_id,omitempty"`
	// RequireReview sends the persona's attempts to close a task through a task_review gate.
	RequireReview bool `json:"require_review"`
	// ReviewerPersonaID (outra persona) ou ReviewerAgent/ReviewerModel (o mesmo papel em outro
	// harness/modelo) mandam o fechamento da task por uma revisão automática antes do gate humano.
	// Os dois são exclusivos; sem nenhum, o gate abre direto.
	ReviewerPersonaID *ID       `json:"reviewer_persona_id,omitempty"`
	ReviewerAgent     string    `json:"reviewer_agent,omitempty"`
	ReviewerModel     string    `json:"reviewer_model,omitempty"`
	PauseReason       string    `json:"pause_reason,omitempty"`
	CreatedAt         time.Time `json:"created_at"`
	UpdatedAt         time.Time `json:"updated_at"`
}

// PersonaIcons é o catálogo fechado de glifos de persona (Kubo DS: glifo de linha monocromático num círculo
// neutro, nunca cor nem emoji). A UI desenha só estes; a ordem é a do seletor.
var PersonaIcons = []string{
	"bot", "code", "search", "pen-line", "shield-check", "trending-up", "cpu", "database", "palette",
	"megaphone", "scale", "book-open", "wrench", "headphones", "rocket", "briefcase", "sparkles", "globe",
}

// DefaultPersonaIcon é o glifo de quem não escolheu nenhum.
const DefaultPersonaIcon = "bot"

// ValidPersonaIcon diz se name está no catálogo.
func ValidPersonaIcon(name string) bool {
	for _, i := range PersonaIcons {
		if i == name {
			return true
		}
	}
	return false
}

// HasReviewer diz se o fechamento de tasks desta persona passa por uma revisão automática.
func (p Persona) HasReviewer() bool { return HasReviewer(p.ReviewerPersonaID, p.ReviewerAgent) }

// HasReviewer é HasReviewer de Persona para quem só tem os campos soltos (linhas do banco).
func HasReviewer(persona *ID, agent string) bool { return persona != nil || agent != "" }

// TaskStatus follows the UI lists.
type TaskStatus string

const (
	TaskBacklog    TaskStatus = "backlog"
	TaskTodo       TaskStatus = "todo"
	TaskInProgress TaskStatus = "in_progress"
	TaskInReview   TaskStatus = "in_review"
	TaskBlocked    TaskStatus = "blocked"
	TaskDone       TaskStatus = "done"
	TaskCancelled  TaskStatus = "cancelled"
)

// TaskStatuses lists every task status in board order.
var TaskStatuses = []TaskStatus{TaskBacklog, TaskTodo, TaskInProgress, TaskInReview, TaskBlocked, TaskDone, TaskCancelled}

func (s TaskStatus) Valid() bool {
	switch s {
	case TaskBacklog, TaskTodo, TaskInProgress, TaskInReview, TaskBlocked, TaskDone, TaskCancelled:
		return true
	}
	return false
}

// Open reports whether the task still expects work.
func (s TaskStatus) Open() bool { return s != TaskDone && s != TaskCancelled }

// Workable reports whether the heartbeat should wake the assignee for this task.
func (s TaskStatus) Workable() bool { return s == TaskTodo || s == TaskInProgress }

type Priority string

const (
	PriorityCritical Priority = "critical"
	PriorityHigh     Priority = "high"
	PriorityMedium   Priority = "medium"
	PriorityLow      Priority = "low"
)

func (p Priority) Valid() bool {
	switch p {
	case PriorityCritical, PriorityHigh, PriorityMedium, PriorityLow:
		return true
	}
	return false
}

// Task is a unit of work assigned to a persona.
type Task struct {
	ID          ID         `json:"id"`
	CompanyID   ID         `json:"company_id"`
	Number      int64      `json:"number"`
	Key         string     `json:"key"` // "<prefix>-<number>", derived
	Title       string     `json:"title"`
	Description string     `json:"description"`
	Status      TaskStatus `json:"status"`
	Priority    Priority   `json:"priority"`
	PersonaID   *ID        `json:"persona_id,omitempty"`
	ProjectID   *ID        `json:"project_id,omitempty"`
	WorkspaceID *ID        `json:"workspace_id,omitempty"`
	ParentID    *ID        `json:"parent_id,omitempty"`
	GoalID      *ID        `json:"goal_id,omitempty"` // meta a que a task serve (ADR-0028)
	Model       string     `json:"model,omitempty"`   // manual model choice; wins over the persona's
	CreatedBy   Actor      `json:"created_by"`
	CreatedAt   time.Time  `json:"created_at"`
	UpdatedAt   time.Time  `json:"updated_at"`
	ClosedAt    *time.Time `json:"closed_at,omitempty"`
}

// Comment is a message on a task thread.
type Comment struct {
	ID        ID        `json:"id"`
	CompanyID ID        `json:"company_id"`
	TaskID    ID        `json:"task_id"`
	Author    Actor     `json:"author"`
	RunID     *ID       `json:"run_id,omitempty"`
	Body      string    `json:"body"`
	EventID   string    `json:"event_id,omitempty"`
	CreatedAt time.Time `json:"created_at"`
	// Anchor is the passage this comment is about (nil on a plain comment); AnchorState says where that
	// passage is in the current version of its document (filled when comments are listed or created).
	Anchor      *Anchor      `json:"anchor,omitempty"`
	AnchorState *AnchorState `json:"anchor_state,omitempty"`
}

// RunStatus is the lifecycle of an execution.
type RunStatus string

const (
	RunQueued      RunStatus = "queued"
	RunRunning     RunStatus = "running"
	RunDone        RunStatus = "done"
	RunInterrupted RunStatus = "interrupted"
	RunFailed      RunStatus = "failed"
	RunCancelled   RunStatus = "cancelled"
	RunExpired     RunStatus = "expired"
)

func (s RunStatus) Valid() bool {
	switch s {
	case RunQueued, RunRunning, RunDone, RunInterrupted, RunFailed, RunCancelled, RunExpired:
		return true
	}
	return false
}

// Active reports whether the run occupies the task (at most one active run per task).
func (s RunStatus) Active() bool { return s == RunQueued || s == RunRunning }

// Terminal reports whether the run has finished.
func (s RunStatus) Terminal() bool { return !s.Active() }

// RunTrigger records why a run started.
type RunTrigger string

const (
	TriggerAssign    RunTrigger = "assign"
	TriggerComment   RunTrigger = "comment"
	TriggerManual    RunTrigger = "manual"
	TriggerHeartbeat RunTrigger = "heartbeat"
	TriggerGate      RunTrigger = "gate" // a human decided a gate the persona was waiting on
	TriggerFlow      RunTrigger = "flow"
	TriggerReview    RunTrigger = "review" // revisão headless que antecede o gate task_review
	TriggerChat      RunTrigger = "chat"   // mensagem humana numa conversa (sem task; ADR-0027)
	TriggerMemory    RunTrigger = "memory" // consolidação de memória: run de sistema da persona curadora (ADR-0030)
)

// CostSource tells where a run's cost came from.
type CostSource string

const (
	CostReported  CostSource = "reported"  // informed by the harness
	CostEstimated CostSource = "estimated" // computed from the price table
	CostNone      CostSource = "none"      // unknown
)

// ModelSource tells who chose the model of a run. Precedence: task (manual) > persona > harness default.
type ModelSource string

const (
	ModelFromTask           ModelSource = "task"
	ModelFromPersona        ModelSource = "persona"
	ModelFromHarnessDefault ModelSource = "harness_default"
)

// ResolveModel applies the precedence manual (task) > persona > harness default (empty model).
func ResolveModel(taskModel, personaModel string) (string, ModelSource) {
	switch {
	case taskModel != "":
		return taskModel, ModelFromTask
	case personaModel != "":
		return personaModel, ModelFromPersona
	}
	return "", ModelFromHarnessDefault
}

// Subscription (Assinatura) is a plan of a harness: monthly fee, the model prefixes it covers and a
// weekly guard. WeeklyLimitUSD is the weekly ceiling; once the week's estimated usage reaches
// WeeklyGuardPct of it, new runs covered by the subscription are blocked until the next week.
type Subscription struct {
	ID             ID         `json:"id"`
	CompanyID      ID         `json:"company_id"`
	Name           string     `json:"name"`
	Agent          string     `json:"agent"` // harness/provider: claude, codex…
	MonthlyUSD     float64    `json:"monthly_usd"`
	ModelPrefixes  []string   `json:"model_prefixes"`
	WeeklyLimitUSD *float64   `json:"weekly_limit_usd,omitempty"`
	WeeklyGuardPct int        `json:"weekly_guard_pct"`
	Active         bool       `json:"active"`
	EndedAt        *time.Time `json:"ended_at,omitempty"`
	CreatedAt      time.Time  `json:"created_at"`
	UpdatedAt      time.Time  `json:"updated_at"`
}

// Covers reports whether a run of agent with model falls under the subscription. An empty model
// (the harness default) belongs to the plan; with no prefixes every model of the harness does.
func (s Subscription) Covers(agent, model string) bool {
	if !s.Active || s.Agent != agent {
		return false
	}
	if len(s.ModelPrefixes) == 0 || model == "" {
		return true
	}
	for _, p := range s.ModelPrefixes {
		if strings.HasPrefix(model, p) {
			return true
		}
	}
	return false
}

// Usage holds token counts reported by the agent.
type Usage struct {
	InputTokens         int64 `json:"input_tokens"`
	OutputTokens        int64 `json:"output_tokens"`
	CacheReadTokens     int64 `json:"cache_read_tokens"`
	CacheCreationTokens int64 `json:"cache_creation_tokens"`
}

// Run is one execution of a persona over a task.
type Run struct {
	ID        ID     `json:"id"`
	Name      string `json:"name,omitempty"` // nome amigável Adjetivo_Substantivo, único na empresa (vazio em runs antigas sem backfill)
	CompanyID ID     `json:"company_id"`
	// TaskID é o zero (uuid nil) numa run de chat, que pertence a uma conversa e não a uma task.
	TaskID ID `json:"task_id"`
	// ConversationID é a conversa de uma run de chat; nil nas demais.
	ConversationID *ID        `json:"conversation_id,omitempty"`
	PersonaID      ID         `json:"persona_id"`
	Status         RunStatus  `json:"status"`
	Trigger        RunTrigger `json:"trigger"`
	Agent          string     `json:"agent"`
	Model          string     `json:"model,omitempty"`
	SessionRef     string     `json:"session_ref,omitempty"`
	TraceID        string     `json:"trace_id,omitempty"`
	ExitCode       *int       `json:"exit_code,omitempty"`
	Error          string     `json:"error,omitempty"`
	Summary        string     `json:"summary,omitempty"`
	CostUSD        *float64   `json:"cost_usd,omitempty"`
	CostSource     CostSource `json:"cost_source,omitempty"`
	// ListCostUSD is tokens x the list price in force when the run finished (stored once, never recalculated).
	ListCostUSD    *float64    `json:"list_cost_usd,omitempty"`
	ModelSource    ModelSource `json:"model_source,omitempty"`
	SubscriptionID *ID         `json:"subscription_id,omitempty"`
	// WorkspaceID and WorkspaceSource record which workspace the run used and why (empty source = older run).
	WorkspaceID     *ID             `json:"workspace_id,omitempty"`
	WorkspaceSource WorkspaceSource `json:"workspace_source,omitempty"`
	Usage           Usage           `json:"usage"`
	HandoffIn       string          `json:"handoff_in,omitempty"`
	HandoffOut      string          `json:"handoff_out,omitempty"`
	CreatedAt       time.Time       `json:"created_at"`
	StartedAt       *time.Time      `json:"started_at,omitempty"`
	FinishedAt      *time.Time      `json:"finished_at,omitempty"`
}

// RunEventKind classifies a line of the run log.
type RunEventKind string

const (
	EventSystem     RunEventKind = "system"
	EventAssistant  RunEventKind = "assistant"
	EventThinking   RunEventKind = "thinking"
	EventToolUse    RunEventKind = "tool_use"
	EventToolResult RunEventKind = "tool_result"
	EventStdout     RunEventKind = "stdout"
	EventStderr     RunEventKind = "stderr"
	EventResult     RunEventKind = "result"
	EventStatus     RunEventKind = "status"
)

// RunEvent is one entry of a run log, ordered by Seq within the run.
type RunEvent struct {
	ID         ID              `json:"id"`
	CompanyID  ID              `json:"company_id"`
	RunID      ID              `json:"run_id"`
	Seq        int64           `json:"seq"`
	Kind       RunEventKind    `json:"kind"`
	Text       string          `json:"text"`
	Payload    json.RawMessage `json:"payload,omitempty"`
	OccurredAt time.Time       `json:"occurred_at"`
	ReceivedAt time.Time       `json:"received_at"`
}

// ActivityEvent is a domain fact, written in the same transaction as the change.
// EventID is a deterministic idempotency key (unique per company) when the
// writer can retry (agents, MCP, outbox); empty otherwise.
type ActivityEvent struct {
	ID          ID              `json:"id"`
	CompanyID   ID              `json:"company_id"`
	Actor       Actor           `json:"actor"`
	Verb        string          `json:"verb"` // e.g. task.created, run.finished
	SubjectType string          `json:"subject_type"`
	SubjectID   ID              `json:"subject_id"`
	Data        json.RawMessage `json:"data,omitempty"`
	EventID     string          `json:"event_id,omitempty"`
	OccurredAt  time.Time       `json:"occurred_at"`
	ReceivedAt  time.Time       `json:"received_at"`
}

// ParseID parses a UUID string.
func ParseID(s string) (ID, error) {
	id, err := uuid.Parse(s)
	if err != nil {
		return ID{}, Invalid("id", "not a uuid")
	}
	return id, nil
}

// Flow is a recurring definition: on each cron occurrence it creates a task assigned to a persona.
type Flow struct {
	ID              ID         `json:"id"`
	CompanyID       ID         `json:"company_id"`
	Slug            string     `json:"slug"`
	Name            string     `json:"name"`
	Description     string     `json:"description,omitempty"`
	Cron            string     `json:"cron"` // 5 fields
	Timezone        string     `json:"timezone"`
	Enabled         bool       `json:"enabled"`
	PersonaID       ID         `json:"persona_id"`
	ProjectID       *ID        `json:"project_id,omitempty"`
	Priority        Priority   `json:"priority"`
	TaskTitle       string     `json:"task_title"`       // template: {{data}}, {{n}}
	TaskDescription string     `json:"task_description"` // same placeholders
	LastFiredAt     *time.Time `json:"last_fired_at,omitempty"`
	NextFireAt      *time.Time `json:"next_fire_at,omitempty"`
	CreatedAt       time.Time  `json:"created_at"`
	UpdatedAt       time.Time  `json:"updated_at"`
}

// FlowFire is one firing of a flow; (FlowID, ScheduledFor) is unique.
type FlowFire struct {
	ID           ID        `json:"id"`
	FlowID       ID        `json:"flow_id"`
	CompanyID    ID        `json:"company_id"`
	ScheduledFor time.Time `json:"scheduled_for"`
	TaskID       *ID       `json:"task_id,omitempty"`
	Manual       bool      `json:"manual,omitempty"` // "Rodar agora", not a cron occurrence
	CreatedAt    time.Time `json:"created_at"`
}
